@Override public void OnFileOperationComplete(FileOperationsVariants currentFileOperation,boolean fileOperationResult,final String path,final String tag,final List<String> lines){
  if (SettingsActivity.dialogFragment != null) {
    SettingsActivity.dialogFragment.dismiss();
    SettingsActivity.dialogFragment=null;
  }
  if (fileOperationResult && currentFileOperation == readTextFile) {
    settingsActivity.runOnUiThread(new Runnable(){
      @Override public void run(){
        try {
          switch (tag) {
            case SettingsActivity.dnscrypt_proxy_toml_tag:          readDnscryptProxyToml(lines); break;
            case SettingsActivity.tor_conf_tag:      readTorConf(lines); break;
            case SettingsActivity.itpd_conf_tag:  readITPDconf(lines); break;
            case SettingsActivity.public_resolvers_md_tag:readPublicResolcersMd(path,lines); break;
            case SettingsActivity.rules_tag:readRules(path,lines); break;
          }
        } catch (IndexOutOfBoundsException e) {
          e.printStackTrace();
        }
      }
    });
  }
  else if (!fileOperationResult && currentFileOperation == readTextFile) {
    if (tag.equals(SettingsActivity.rules_tag)) {
      readRules(path,lines);
    }
  }
  else if (fileOperationResult && currentFileOperation == writeToTextFile) {
    settingsActivity.runOnUiThread(new Runnable(){
      @Override public void run(){
        Toast.makeText(settingsActivity,settingsActivity.getText(R.string.toastSettings_saved),Toast.LENGTH_SHORT).show();
      }
    });
  }
}
